import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.AfterEach;
import static org.junit.jupiter.api.Assertions.*;

class DatabaseServiceTest {

    private DatabaseService databaseService;

    @BeforeEach
    void setUp() {
        databaseService = new DatabaseService();
    }

    @AfterEach
    void tearDown() {
        if (databaseService != null) {
            databaseService.disconnect();
        }
    }

    @Test
    void testDatabaseServiceConstructor() {
        assertNotNull(databaseService);
    }

    @Test
    void testConnect() {
        // Test the connect method - should not throw exception
        assertDoesNotThrow(() -> {
            databaseService.connect();
        });
    }

    @Test
    void testExecuteQueryWithValidConnection() {
        // First connect to database
        databaseService.connect();

        // Test executing a query
        assertDoesNotThrow(() -> {
            databaseService.executeQuery("SELECT 1");
        });
    }

    @Test
    void testExecuteQueryWithNullSql() {
        databaseService.connect();

        // Test with null SQL - should handle gracefully
        assertDoesNotThrow(() -> {
            databaseService.executeQuery(null);
        });
    }

    @Test
    void testExecuteQueryWithEmptySql() {
        databaseService.connect();

        // Test with empty SQL
        assertDoesNotThrow(() -> {
            databaseService.executeQuery("");
        });
    }

    @Test
    void testExecuteQueryWithoutConnection() {
        // Test executing query without connecting first
        assertDoesNotThrow(() -> {
            databaseService.executeQuery("SELECT 1");
        });
    }

    @Test
    void testDisconnect() {
        // Test disconnect without connection
        assertDoesNotThrow(() -> {
            databaseService.disconnect();
        });
    }

    @Test
    void testDisconnectAfterConnect() {
        databaseService.connect();

        // Test disconnect after connection
        assertDoesNotThrow(() -> {
            databaseService.disconnect();
        });
    }

    @Test
    void testMultipleConnects() {
        // Test multiple connect calls
        assertDoesNotThrow(() -> {
            databaseService.connect();
            databaseService.connect();
            databaseService.connect();
        });
    }

    @Test
    void testMultipleDisconnects() {
        databaseService.connect();

        // Test multiple disconnect calls
        assertDoesNotThrow(() -> {
            databaseService.disconnect();
            databaseService.disconnect();
            databaseService.disconnect();
        });
    }

    @Test
    void testComplexSqlQuery() {
        databaseService.connect();

        String complexSql = "SELECT u.id, u.name, p.title FROM users u JOIN posts p ON u.id = p.user_id WHERE u.active = 1 ORDER BY u.name";

        assertDoesNotThrow(() -> {
            databaseService.executeQuery(complexSql);
        });
    }

    @Test
    void testSqlInjectionAttempt() {
        databaseService.connect();

        String maliciousSql = "SELECT * FROM users WHERE id = 1; DROP TABLE users; --";

        assertDoesNotThrow(() -> {
            databaseService.executeQuery(maliciousSql);
        });
    }
}

