    private final ByteArrayOutputStream errContent = new ByteArrayOutputStream();
    private final PrintStream originalOut = System.out;
    private final PrintStream originalErr = System.err;

    @BeforeEach
    void setUpStreams() {
        System.setOut(new PrintStream(outContent));
        System.setErr(new PrintStream(errContent));
    }

    @AfterEach
    void restoreStreams() {
        System.setOut(originalOut);
        System.setErr(originalErr);
    }

    @Test
    void testMainMethod() {
        String[] args = {};

        assertDoesNotThrow(() -> {
            MiniApp.main(args);
        });

        String output = outContent.toString();
        assertTrue(output.contains("Starting Mini Java Application..."));
    }

    @Test
    void testMainMethodWithNullArgs() {
        assertDoesNotThrow(() -> {
            MiniApp.main(null);
        });

        String output = outContent.toString();
        assertTrue(output.contains("Starting Mini Java Application..."));
    }

    @Test
    void testMainMethodWithArgs() {
        String[] args = {"arg1", "arg2", "arg3"};

        assertDoesNotThrow(() -> {
            MiniApp.main(args);
        });

        String output = outContent.toString();
        assertTrue(output.contains("Starting Mini Java Application..."));
    }

    @Test
    void testApplicationInitialization() {
        MiniApp app = new MiniApp();

        assertDoesNotThrow(() -> {
            // This will call initializeApplication through main
            String[] args = {};
            MiniApp.main(args);
        });

        String output = outContent.toString();
        assertTrue(output.contains("Starting Mini Java Application..."));
    }

    @Test
    void testConfigurationLoading() {
        assertDoesNotThrow(() -> {
            MiniApp.main(new String[]{});
        });

        String output = outContent.toString();
        // Should contain warning about config file not found (expected behavior)
        assertTrue(output.contains("Warning: Configuration file not found") ||
                  output.contains("Configuration loaded"));
    }

    @Test
